/// <summary>
/// The IR's published JSON Schema, <c>schemas/haruspex.ir.schema.json</c>: generated by <see cref="IrJsonSchema"/>, committed,
/// and held to the model, the writer and the reader. The committed file must be what the generator gives today; every IR
/// file haruspex writes must pass it; a broken file must fail it and the reader alike; and every property of every IR record
/// must be in it, or be named here as written another way.
/// </summary>
public class IrJsonSchemaTests
{
