    /// <summary>Ways to break a valid file, each of which the schema and the reader must both refuse.</summary>
    private static readonly Dictionary<string, Action<JsonObject>> Breakages = new(StringComparer.Ordinal)
    {
        ["another version"] = json => json["irVersion"] = "0.14",
        ["a required property missing"] = json => Result(json).Remove("cardinality"),
        ["a flag that is not a boolean"] = json => json["objects"]![0]!["parameters"]![0]!["hasDefault"] = "no",
        ["an unknown property"] = json => Field(json)["colour"] = "red",
        ["an unknown null rule"] = json => Field(json)["nullableBecause"]![0]!["rule"] = "outer-applied",
        ["an unknown type kind"] = json => Field(json)["type"]!["kind"] = "money",
        ["a named type that is not an object"] = json => json["types"]!["OrderRow"]!["kind"] = "record",
        ["nullable without reasons"] = json => Field(json).Remove("nullableBecause"),
        ["reasons for a value never null"] = json => Field(json)["nullable"] = false,
        ["an empty list of reasons"] = json => Field(json)["nullableBecause"] = new JsonArray(),
        ["a fact source of an unknown kind"] = json => Field(json)["type"]!["maxLength"]!["from"] = new JsonObject { ["guess"] = "x" },
        ["a fact with two sources"] = json => Field(json)["type"]!["maxLength"]!["from"]!["check"] = "ck",
        ["a fixed length and a maximum"] = json => Field(json)["type"]!["length"] = Field(json)["type"]!["maxLength"]!.DeepClone(),
        ["a union of one variant"] = json => json["types"]!["OrderRow"]!["fields"]![8]!["type"]!["variants"]!.AsArray().RemoveAt(1),
        ["a canonical set without its fold"] = json => json["types"]!["OrderRow"]!["fields"]![2]!["type"]!["values"]!.AsObject().Remove("fold"),
        ["a fold on a set that is not canonical"] = json => json["types"]!["OrderRow"]!["fields"]![2]!["type"]!["values"]!["match"] = "exact",
        ["an identity with two owners"] = json => json["types"]!["OrderRow"]!["identity"]!["function"] = "sales.line_tree",
        ["results that are neither listed nor null"] = json => json["objects"]![0]!["results"] = "none",
        ["an absent result without reasons"] = json => Result(json).Remove("absentBecause"),
        ["a negative count"] = json => Field(json)["type"]!["maxLength"]!["value"] = -1,
        ["a count past 32 bits"] = json => json["types"]!["OrderRow"]!["fields"]![3]!["type"]!["maxItems"] = 4294967296,
    };

    public static TheoryData<string> BreakageNames { get; } = [.. Breakages.Keys];

    public static TheoryData<string> Snapshots { get; } =
        [.. Fixture.All.SelectMany(f => f.Snapshots).Select(s => Path.GetRelativePath(RepositoryPaths.Fixtures, s.Ir))];

    private static string SchemaPath => Path.Combine(RepositoryPaths.Root, SchemaFile);

    [Fact]
    public void The_committed_schema_is_what_the_model_generates()
    {
        var generated = IrJsonSchema.Write();
        var committed = File.Exists(SchemaPath) ? File.ReadAllText(SchemaPath).ReplaceLineEndings("\n") : null;
        if (committed == generated)
            return;

        // As SnapshotStore does: rewritten only when asked, and never in CI.
        if (Environment.GetEnvironmentVariable(SnapshotStore.AcceptVariable) == "1" && !SnapshotStore.IsCiEnvironment(Environment.GetEnvironmentVariable))
        {
            File.WriteAllText(SchemaPath, generated);
            return;
        }

        Assert.Fail(
            $"{SchemaFile} is not what IrJsonSchema generates from the model today. Regenerate it with " +
            $"{SnapshotStore.AcceptVariable}=1 dotnet test --filter {nameof(IrJsonSchemaTests)}, and read the diff. The difference:\n" +
            SnapshotStore.UnifiedDiff(committed ?? "", generated, SchemaFile, "what IrJsonSchema generates"));
    }

    [Fact]
    public void The_schema_is_a_2020_12_schema_with_its_id_and_the_current_version()
    {
        using var schema = JsonDocument.Parse(IrJsonSchema.Write());

        Assert.Equal("https://json-schema.org/draft/2020-12/schema", schema.RootElement.GetProperty("$schema").GetString());
        Assert.Equal(IrJsonSchema.Id, schema.RootElement.GetProperty("$id").GetString());
        Assert.Equal(IrDocument.CurrentVersion, schema.RootElement.GetProperty("properties").GetProperty("irVersion").GetProperty("const").GetString());
    }

    [Fact]
    public void Every_null_rule_is_in_the_schema_by_its_wire_name() =>
        Assert.Equal(
            Enum.GetValues<IrNullRule>().Select(IrWireNames.Of),
            Definition("reason").GetProperty("properties").GetProperty("rule").GetProperty("enum").EnumerateArray().Select(e => e.GetString()));

    [Theory]
    [MemberData(nameof(Snapshots))]
    public void Every_committed_ir_file_passes_the_schema(string snapshot) =>
        AssertValid(File.ReadAllText(Path.Combine(RepositoryPaths.Fixtures, snapshot)));

    [Fact]
    public void What_every_fixture_infers_passes_the_schema() =>
        Assert.All(Fixture.All, f => AssertValid(IrJsonWriter.Write(f.Ir)));

    [Fact]
    public void What_both_corpora_infer_passes_the_schema() =>
        Assert.All(Corpus.Corpus.Runs, r => AssertValid(IrJsonWriter.Write(r.Document)));

    [Fact]
    public void The_sample_with_every_node_passes_the_schema() => AssertValid(IrJsonWriter.Write(IrSamples.Everything));

    [Theory]
    [MemberData(nameof(BreakageNames))]
    public void A_broken_file_fails_the_schema_and_the_reader_alike(string breakage)
    {
        var json = JsonNode.Parse(IrJsonWriter.Write(IrSamples.Everything))!.AsObject();
        Breakages[breakage](json);
        var text = json.ToJsonString();

        using var instance = JsonDocument.Parse(text);
        Assert.NotEmpty(Schema().Validate(instance.RootElement));
        Assert.Throws<IrFormatException>(() => IrJsonReader.Read(text));
    }

    [Fact]
    public void Every_property_of_every_ir_record_is_in_the_schema()
    {
        var records = typeof(IrDocument).Assembly.GetExportedTypes()
            .Where(t => t.GetMethod("<Clone>$") is not null && !t.IsAbstract && !t.IsSubclassOf(typeof(IrPathSegment)));
        var properties = records.SelectMany(t => t.GetProperties(BindingFlags.Public | BindingFlags.Instance).Select(p => $"{t.Name}.{p.Name}"));

        Assert.Equal(properties.Order(StringComparer.Ordinal), Properties.Select(p => $"{p.Record.Name}.{p.Property}").Order(StringComparer.Ordinal));
        Assert.All(
            Properties.Where(p => p.Key is not null),
            p => Assert.True(PropertiesOf(p.Definition).TryGetProperty(p.Key!, out _), $"{p.Record.Name}.{p.Property}: the schema's {p.Definition} has no {p.Key}."));
    }

    private static void AssertValid(string json)
    {
        using var instance = JsonDocument.Parse(json);
        Assert.Empty(Schema().Validate(instance.RootElement));
    }

    private static SchemaSubset Schema()
    {
        using var schema = JsonDocument.Parse(File.ReadAllText(SchemaPath));
        return new SchemaSubset(schema.RootElement.Clone());
    }

    private static JsonElement Definition(string name)
    {
        using var schema = JsonDocument.Parse(IrJsonSchema.Write());
        return schema.RootElement.GetProperty("$defs").GetProperty(name).Clone();
    }

    /// <summary>The properties a definition lists: the document's own for "", its source's for "document.source".</summary>
    private static JsonElement PropertiesOf(string definition)
    {
        using var schema = JsonDocument.Parse(IrJsonSchema.Write());
        var root = schema.RootElement.GetProperty("properties");
        return (definition switch
        {
            "" => root,
            "document.source" => root.GetProperty("source").GetProperty("properties"),
            _ => schema.RootElement.GetProperty("$defs").GetProperty(definition).GetProperty("properties"),
        }).Clone();
    }

    private static JsonObject Field(JsonObject json) => json["types"]!["OrderRow"]!["fields"]![0]!.AsObject();

    private static JsonObject Result(JsonObject json) => json["objects"]![0]!["results"]![0]!.AsObject();
}
